insert into public.sense_distractors (sense_id, distractor, relation_type)
select s.id, i.distractor, i.relation_type
from incoming i
join public.words w on w.headword = i.headword and w.pos = i.pos
join public.senses s on s.word_id = w.id and s.sense_index = i.sense_index
on conflict (sense_id, distractor) do nothing;

